{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Codeine, a 3-methoxy-N-methyl morphinan, has absolute oral bioavailability of 42–71% in healthy volunteers; the shared N-methyl and 3-methoxy substitution pattern supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a closely related morphinan opioid, has absolute oral bioavailability of 41% in humans, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Samidorphan, another morphinan with a 6-keto/14-hydroxy motif, has absolute oral bioavailability of 68.6%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Naltrexone has low oral bioavailability (~5%), but this is associated with its phenolic 3-OH and N-cyclopropylmethyl groups; the query's 3-methoxy and N-methyl groups remove these major first-pass liabilities, so this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is oxycodone, a 3-methoxy-N-methyl-14-hydroxy-morphinan-6-one. Multiple close morphinan analogues with the same N-methyl/3-methoxy or 6-keto/14-hydroxy features show F ≥ 40–70%, and the low-F naltrexone data are not transferable because the query lacks its phenolic and N-cyclopropylmethyl metabolic liabilities. Therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct oxycodone bioavailability record is present in the supplied evidence set; prediction relies on close analogues and known pharmacology.",
    "Naltrexone low-F data are from a close scaffold but differ at key metabolic positions, limiting direct transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

